fn swap_first_and_last(a: &Vec<i32>) -> Vec<i32> {
    // Clone the input to create the result vector
    let mut result = a.clone();
    let n = result.len();
    
    // If there's more than one element, swap the first and last
    if n > 1 {
        result.swap(0, n - 1);
    }
    
    result
}

// Example usage and basic test
fn main() {
    let v1 = vec![1, 2, 3, 4];
    let v2 = vec![7];
    let v3 = vec![10, 20];

    assert_eq!(swap_first_and_last(&v1), vec![4, 2, 3, 1]);
    assert_eq!(swap_first_and_last(&v2), vec![7]);
    assert_eq!(swap_first_and_last(&v3), vec![20, 10]);

    println!("All tests passed!");
}